:root {
  --bg: #1a1a2e;
  --card: #16213e;
  --accent: #e94560;
  --accent2: #0f3460;
  --text: #e0e0e0;
  --step-off: #0f3460;
  --step-on: #e94560;
  --playhead: #f5c518;
  --font: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  background: var(--bg);
  font-family: var(--font);
  font-size: 16px;
  color: var(--text);
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 20px;
}

.app {
  background: var(--card);
  border-radius: 16px;
  padding: 28px 24px;
  max-width: 720px;
  width: 100%;
  box-shadow: 0 8px 32px rgba(0,0,0,0.4);
}

h1 {
  font-size: 1.6rem;
  text-align: center;
  margin-bottom: 20px;
  letter-spacing: 1px;
  color: var(--accent);
  text-shadow: 0 0 8px rgba(233,69,96,0.4);
}

.controls {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 12px;
  margin-bottom: 20px;
  justify-content: center;
}

.btn {
  background: var(--accent2);
  color: var(--text);
  border: 2px solid var(--accent);
  border-radius: 8px;
  padding: 10px 24px;
  font-size: 1rem;
  font-family: var(--font);
  cursor: pointer;
  transition: background 0.15s, transform 0.1s;
  min-width: 90px;
}

.btn:hover {
  background: var(--accent);
  color: #fff;
}

.btn:focus-visible {
  outline: 3px solid var(--playhead);
  outline-offset: 2px;
}

.btn:active {
  transform: scale(0.95);
}

.btn.playing {
  background: var(--accent);
  color: #fff;
}

label[for="bpmInput"] {
  font-size: 1rem;
  font-weight: 600;
}

#bpmInput {
  width: 80px;
  padding: 8px;
  font-size: 1rem;
  font-family: var(--font);
  border: 2px solid var(--accent);
  border-radius: 8px;
  background: var(--bg);
  color: var(--text);
  text-align: center;
}

#bpmInput:focus-visible {
  outline: 3px solid var(--playhead);
  outline-offset: 2px;
}

.grid-container {
  overflow-x: auto;
}

.grid-header {
  display: grid;
  grid-template-columns: 80px repeat(8, 1fr);
  gap: 6px;
  margin-bottom: 6px;
}

.corner {
  min-height: 20px;
}

.col-label {
  text-align: center;
  font-size: 0.85rem;
  font-weight: 600;
  opacity: 0.7;
  min-width: 36px;
}

.grid {
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.row {
  display: grid;
  grid-template-columns: 80px repeat(8, 1fr);
  gap: 6px;
  align-items: center;
}

.instrument-label {
  font-size: 0.85rem;
  font-weight: 600;
  text-align: right;
  padding-right: 8px;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.step {
  aspect-ratio: 1;
  min-width: 36px;
  min-height: 36px;
  background: var(--step-off);
  border: 2px solid transparent;
  border-radius: 6px;
  cursor: pointer;
  transition: background 0.1s, border-color 0.1s, transform 0.1s;
  padding: 0;
}

.step:hover {
  border-color: var(--accent);
}

.step:focus-visible {
  outline: 3px solid var(--playhead);
  outline-offset: 2px;
}

.step:active {
  transform: scale(0.9);
}

.step.on {
  background: var(--step-on);
  box-shadow: 0 0 8px rgba(233,69,96,0.6);
}

.step.playhead {
  border-color: var(--playhead);
  box-shadow: 0 0 10px var(--playhead);
}

@media (max-width: 480px) {
  .app {
    padding: 20px 14px;
  }
  h1 {
    font-size: 1.3rem;
  }
  .grid-header, .row {
    grid-template-columns: 60px repeat(8, 1fr);
  }
  .instrument-label {
    font-size: 0.75rem;
  }
  .step {
    min-width: 28px;
    min-height: 28px;
  }
  .btn {
    padding: 8px 16px;
    font-size: 0.9rem;
    min-width: 70px;
  }
  #bpmInput {
    width: 64px;
    padding: 6px;
  }
}

const INSTRUMENTS = ['Kick', 'Snare', 'Hi-Hat', 'Clap'];
const STEPS = 8;
let state = Array.from({ length: 4 }, () => Array(STEPS).fill(false));
let isPlaying = false;
let currentStep = -1;
let intervalId = null;

const gridEl = document.getElementById('grid');
const playBtn = document.getElementById('playBtn');
const clearBtn = document.getElementById('clearBtn');
const bpmInput = document.getElementById('bpmInput');

let audioCtx = null;

function ensureAudio() {
  if (!audioCtx) {
    audioCtx = new (window.AudioContext || window.webkitAudioContext)();
  }
  if (audioCtx.state === 'suspended') {
    audioCtx.resume();
  }
}

function playTone(freq, duration = 0.1) {
  if (!audioCtx) return;
  const osc = audioCtx.createOscillator();
  const gain = audioCtx.createGain();
  osc.type = 'square';
  osc.frequency.value = freq;
  gain.gain.setValueAtTime(0.15, audioCtx.currentTime);
  gain.gain.exponentialRampToValueAtTime(0.001, audioCtx.currentTime + duration);
  osc.connect(gain);
  gain.connect(audioCtx.destination);
  osc.start();
  osc.stop(audioCtx.currentTime + duration);
}

const FREQS = [80, 200, 400, 600];

function buildGrid() {
  gridEl.innerHTML = '';
  for (let r = 0; r < 4; r++) {
    const row = document.createElement('div');
    row.className = 'row';
    row.setAttribute('role', 'row');
    const label = document.createElement('div');
    label.className = 'instrument-label';
    label.textContent = INSTRUMENTS[r];
    row.appendChild(label);
    for (let c = 0; c < STEPS; c++) {
      const btn = document.createElement('button');
      btn.className = 'step';
      btn.setAttribute('role', 'gridcell');
      btn.setAttribute('aria-label', `${INSTRUMENTS[r]} step ${c + 1}`);
      btn.dataset.row = r;
      btn.dataset.col = c;
      btn.addEventListener('click', () => toggleStep(r, c));
      row.appendChild(btn);
    }
    gridEl.appendChild(row);
  }
}

function toggleStep(r, c) {
  state[r][c] = !state[r][c];
  updateGrid();
}

function updateGrid() {
  const steps = gridEl.querySelectorAll('.step');
  steps.forEach(btn => {
    const r = +btn.dataset.row;
    const c = +btn.dataset.col;
    btn.classList.toggle('on', state[r][c]);
    btn.setAttribute('aria-pressed', state[r][c]);
  });
}

function clearPlayhead() {
  gridEl.querySelectorAll('.step.playhead').forEach(el => el.classList.remove('playhead'));
}

function setPlayhead(col) {
  clearPlayhead();
  if (col < 0) return;
  gridEl.querySelectorAll(`.step[data-col="${col}"]`).forEach(el => el.classList.add('playhead'));
}

function tick() {
  currentStep = (currentStep + 1) % STEPS;
  setPlayhead(currentStep);
  for (let r = 0; r < 4; r++) {
    if (state[r][currentStep]) {
      playTone(FREQS[r]);
    }
  }
}

function startPlayback() {
  ensureAudio();
  isPlaying = true;
  playBtn.textContent = 'Stop';
  playBtn.setAttribute('aria-label', 'Stop');
  playBtn.classList.add('playing');
  currentStep = -1;
  const bpm = Math.max(40, Math.min(240, +bpmInput.value || 120));
  const interval = 60000 / bpm / 2;
  intervalId = setInterval(tick, interval);
}

function stopPlayback() {
  isPlaying = false;
  playBtn.textContent = 'Play';
  playBtn.setAttribute('aria-label', 'Play');
  playBtn.classList.remove('playing');
  clearInterval(intervalId);
  intervalId = null;
  currentStep = -1;
  clearPlayhead();
}

playBtn.addEventListener('click', () => {
  if (isPlaying) stopPlayback();
  else startPlayback();
});

clearBtn.addEventListener('click', () => {
  stopPlayback();
  state = Array.from({ length: 4 }, () => Array(STEPS).fill(false));
  updateGrid();
});

bpmInput.addEventListener('change', () => {
  if (isPlaying) {
    stopPlayback();
    startPlayback();
  }
});

buildGrid();
updateGrid();
